-- =============================================================================
-- 447 — LE CAHIER D'EXERCICES DE TLE (partie 12)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 447 --niveau Tle --matieres physique-chimie --suffixe 12 > supabase/contenu/447_exercices_tle_12.sql
--
-- 93 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   physique-chimie.k184    33 exercices · 11 chapitres
--   physique-chimie.k185    33 exercices · 11 chapitres
--   physique-chimie.k186    27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('302b266f-547d-5e87-a642-e7e6f969fa1d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vinaigre et l’ammoniaque","competence":"analyser-document","situation":"Dans la cuisine, on trouve du vinaigre (acide éthanoïque CH₃COOH) et, dans le placard à produits, de l’ammoniaque (NH₃ dissous). Voici les couples acide/base en jeu.","documents":[{"id":"couples","type":"tableau","titre":"Quatre couples acide/base","colonnes":["Couple","Demi-équation"],"lignes":[["CH₃COOH / CH₃COO⁻","CH₃COOH = CH₃COO⁻ + H⁺"],["NH₄⁺ / NH₃","NH₄⁺ = NH₃ + H⁺"],["H₃O⁺ / H₂O","H₃O⁺ = H₂O + H⁺"],["H₂O / HO⁻","H₂O = HO⁻ + H⁺"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la demi-équation du couple de l’ion ammonium.","aide":"Cherche la ligne qui contient NH₄⁺.","type":"zone","document":"couples","multiple":false},{"enonce":"Complète : on mélange le vinaigre et l’ammoniaque.","aide":"Dans chaque couple du tableau, l’acide est à gauche : celui qui cède H⁺.","type":"trous","segments":["Dans la réaction entre CH₃COOH et NH₃, CH₃COOH joue le rôle d’",0," et NH₃ celui de ",1,"."],"banque":["solvant","acide","catalyseur","base"]},{"enonce":"Quand NH₃ capte un proton, il devient NH₄⁺. Combien d’atomes d’hydrogène compte cet ion ?","aide":"NH₃ en a déjà 3 : ajoute le proton H⁺.","type":"nombre","unite":"atomes"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La deuxième ligne : **NH₄⁺ = NH₃ + H⁺**. L’acide NH₄⁺ cède un proton et devient la base NH₃."},{"cle":{"type":"trous","trous":[["acide"],["base"]]},"affichage":"acide · base","explication":"CH₃COOH cède un proton : c’est l’**acide**. NH₃ capte ce proton pour devenir NH₄⁺ : c’est la **base**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 atomes","explication":"3 + 1 = **4** atomes d’hydrogène : NH₄⁺ est l’ion ammonium."}]$ex$::jsonb),
  ('302b266f-547d-5e87-a642-e7e6f969fa1d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’ion hydrogénocarbonate, double jeu","competence":"analyser-document","situation":"L’ion hydrogénocarbonate HCO₃⁻ est présent dans les eaux minérales et dans le bicarbonate de soude. On l’étudie dans deux réactions, l’une avec un acide, l’autre avec une base.","documents":[{"id":"reactions","type":"tableau","titre":"Deux réactions de HCO₃⁻","colonnes":["Réaction","Réactifs","Produits"],"lignes":[["(1)","HCO₃⁻ + H₃O⁺","CO₂,H₂O + H₂O"],["(2)","HCO₃⁻ + HO⁻","CO₃²⁻ + H₂O"]],"enteteLignes":true,"source":"Réactions données dans le cours"}],"questions":[{"enonce":"Touche les produits de la réaction (2).","aide":"Les produits sont à droite de la flèche, dans la dernière colonne.","type":"zone","document":"reactions","multiple":false},{"enonce":"Associe chaque réaction au rôle de HCO₃⁻.","aide":"Regarde si HCO₃⁻ devient CO₂,H₂O (plus de H) ou CO₃²⁻ (moins de H).","type":"association","gauche":[{"id":"g0","texte":"Réaction (1)"},{"id":"g1","texte":"Réaction (2)"}],"droite":[{"id":"d0","texte":"HCO₃⁻ cède un proton"},{"id":"d1","texte":"HCO₃⁻ capte un proton"}]},{"enonce":"Quelles espèces sont amphotères ? (Plusieurs réponses.)","aide":"Une espèce amphotère appartient à deux couples : acide dans l’un, base dans l’autre.","type":"choix","options":[{"id":"a","texte":"HCO₃⁻"},{"id":"b","texte":"NH₄⁺"},{"id":"c","texte":"CH₃COO⁻"},{"id":"d","texte":"H₂O"}],"multiple":true},{"enonce":"Dans la réaction (2), combien de charges négatives élémentaires portent, au total, les deux réactifs HCO₃⁻ et HO⁻ ?","aide":"Chaque ion porte une charge négative.","type":"nombre","unite":"e"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La réaction (2) forme **CO₃²⁻ + H₂O** : HCO₃⁻ a perdu un proton."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"En (1), HCO₃⁻ gagne un H et devient CO₂,H₂O : il joue le rôle de **base**. En (2), il perd un H et devient CO₃²⁻ : il joue le rôle d’**acide**."},{"cle":{"type":"choix","ids":["a","d"]},"explication":"**H₂O** (couples H₃O⁺/H₂O et H₂O/HO⁻) et **HCO₃⁻** sont amphotères. NH₄⁺ n’est qu’un acide, CH₃COO⁻ n’est qu’une base."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 e","explication":"HCO₃⁻ en porte 1, HO⁻ en porte 1 : **2** au total, comme CO₃²⁻ côté produits. La charge se conserve."}]$ex$::jsonb),
  ('302b266f-547d-5e87-a642-e7e6f969fa1d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Écrire la réaction pas à pas","competence":"raisonner","situation":"Sur une étiquette de produit ménager, on lit : « ne jamais mélanger vinaigre et ammoniaque ». Pour comprendre ce qui se passe, on repère les couples puis on écrit l’équation.","documents":[{"id":"especes","type":"tableau","titre":"Les espèces et leurs couples","colonnes":["Espèce","Couple où elle est acide","Couple où elle est base"],"lignes":[["H₂O","H₂O / HO⁻","H₃O⁺ / H₂O"],["HCO₃⁻","HCO₃⁻ / CO₃²⁻","CO₂,H₂O / HCO₃⁻"],["NH₃","—","NH₄⁺ / NH₃"],["CH₃COOH","CH₃COOH / CH₃COO⁻","—"]],"enteteLignes":true},{"id":"melange","type":"texte","genre":"consigne","titre":"L’expérience","blocs":["On verse un peu de vinaigre (acide éthanoïque CH₃COOH) dans de l’ammoniaque (NH₃ dissous)."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les espèces amphotères du tableau. (Plusieurs réponses.)","aide":"Une espèce amphotère a un couple dans les DEUX colonnes.","type":"zone","document":"especes","multiple":true},{"enonce":"Range les étapes pour écrire l’équation d’une réaction acido-basique.","aide":"On commence par les couples et on finit par une vérification.","type":"ordre","items":[{"id":"a","texte":"Faire passer H⁺ de l’acide à la base"},{"id":"b","texte":"Repérer les deux couples en jeu"},{"id":"c","texte":"Vérifier la conservation des atomes et des charges"},{"id":"d","texte":"Écrire la demi-équation de chaque couple"},{"id":"e","texte":"Additionner les demi-équations"}]},{"enonce":"Quelle est l’équation de la réaction entre CH₃COOH et NH₃ ?","aide":"L’acide CH₃COOH cède H⁺ à la base NH₃. Regarde les formules à droite de la flèche.","type":"choix","options":[{"id":"a","texte":"CH₃COOH + NH₃ → CH₃COO⁻ + NH₄⁺ : l’acide éthanoïque cède son proton à l’ammoniac"},{"id":"b","texte":"CH₃COOH + NH₃ → CH₃COOH₂⁺ + NH₂⁻ : le proton reste sur l’acide"},{"id":"c","texte":"CH₃COO⁻ + NH₄⁺ → CH₃COOH + NH₃ : c’est la réaction dans le sens inverse"},{"id":"d","texte":"CH₃COOH + NH₄⁺ → CH₃COO⁻ + NH₃ : les deux acides réagissent entre eux"}],"multiple":false},{"enonce":"Dans l’eau pure, combien d’ions HO⁻ apparaissent pour chaque ion H₃O⁺ formé par l’autoprotolyse 2 H₂O = H₃O⁺ + HO⁻ ?","aide":"Lis les coefficients de l’équation.","type":"nombre","unite":"ion"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r1c0"]},"explication":"**H₂O** et **HCO₃⁻** figurent dans les deux colonnes : elles sont amphotères. NH₃ n’est que base et CH₃COOH n’est qu’un acide."},{"cle":{"type":"ordre","ids":["b","d","a","e","c"]},"explication":"On repère les couples, on écrit les demi-équations, on fait passer le proton de l’acide à la base, on additionne, puis on **vérifie** atomes et charges."},{"cle":{"type":"choix","ids":["a"]},"explication":"**CH₃COOH + NH₃ → CH₃COO⁻ + NH₄⁺** : le proton passe de l’acide d’un couple à la base de l’autre. Atomes et charges sont conservés."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 ion","explication":"Les coefficients sont 1 et 1 : pour chaque H₃O⁺ il apparaît **1** HO⁻. C’est pourquoi l’eau pure est neutre."}]$ex$::jsonb),
  ('6e051370-fe80-5591-8f9e-2489eb3c9986'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Du citron à la soude","competence":"lire-tableau","situation":"Un laboratoire a mesuré le pH de solutions que l’on croise à la maison. Un soda a un pH de 3,0.","documents":[{"id":"ph","type":"tableau","titre":"pH de quelques solutions","colonnes":["Solution","pH"],"lignes":[["Jus de citron","2,5"],["Lait","6,5"],["Eau pure","7,0"],["Savon liquide","10,0"],["Soude ménagère","13,0"]],"enteteLignes":true,"source":"Valeurs arrondies, mesures à 25 °C"}],"questions":[{"enonce":"Touche le pH de la solution la plus acide.","aide":"Plus le pH est petit, plus la solution est acide.","type":"zone","document":"ph","multiple":false},{"enonce":"Touche les pH des solutions basiques. (Plusieurs réponses.)","aide":"Une solution basique a un pH supérieur à 7 à 25 °C.","type":"zone","document":"ph","multiple":true},{"enonce":"Le jus de citron et le lait diffèrent de 4 unités de pH. Par combien [H₃O⁺] est-elle multipliée du lait au citron ?","aide":"Chaque unité de pH correspond à un facteur 10.","type":"nombre"},{"enonce":"Quelle est la concentration en ions H₃O⁺ d’un soda de pH 3,0, en mmol·L⁻¹ ?","aide":"[H₃O⁺] = 10^(−pH) mol·L⁻¹, puis convertis en mmol·L⁻¹.","type":"nombre","unite":"mmol·L⁻¹"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Le **jus de citron** (pH 2,5) a le pH le plus bas : c’est la solution la plus acide."},{"cle":{"type":"zone","ids":["r3c1","r4c1"]},"explication":"Le **savon liquide** (10,0) et la **soude** (13,0) sont basiques. Le lait (6,5) est très légèrement acide, l’eau pure (7,0) est neutre."},{"cle":{"type":"nombre","valeur":10000,"tolerance":0},"affichage":"10 000","explication":"4 unités de pH : 10⁴ = **10 000**. Le citron est dix mille fois plus concentré en H₃O⁺ que le lait."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 mmol·L⁻¹","explication":"[H₃O⁺] = 10⁻³ mol·L⁻¹ = **1 mmol·L⁻¹**."}]$ex$::jsonb),
  ('6e051370-fe80-5591-8f9e-2489eb3c9986'::uuid, 2, 2, 10, 35, 4,
