  ('65fd6deb-d2a3-5627-947c-0eeb1fab352f'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"La conductance de l’eau de source","competence":"modeliser","situation":"Une eau de source imaginaire ne contient, pour simplifier, que des ions sodium et chlorure. On veut prévoir ce que mesurerait un conductimètre dont la cellule a des électrodes de surface S et distantes de L. On rappelle G = σ × S / L (S et L en mètres).","documents":[{"id":"etiquette","type":"fiche","modele":"etiquette","entete":"Eau de source imaginaire","sousTitre":"Minéralisation, en mg par litre","emoji":"💧","lignes":[{"texte":"Sodium Na⁺","valeur":"23,0 mg/L","id":"z1"},{"texte":"Chlorure Cl⁻","valeur":"35,5 mg/L","id":"z2"}],"pied":"Étiquette écrite pour l’exercice"},{"id":"donnees","type":"tableau","titre":"Données","colonnes":["Donnée","Valeur"],"lignes":[["Masse molaire de Na","23,0 g·mol⁻¹"],["Masse molaire de Cl","35,5 g·mol⁻¹"],["λ(Na⁺)","5,0 mS·m²·mol⁻¹"],["λ(Cl⁻)","7,6 mS·m²·mol⁻¹"],["Surface des électrodes S","2,0 cm²"],["Distance L","1,0 cm"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne de l’étiquette qui donne la quantité d’ions sodium.","aide":"Le sodium a pour symbole Na.","type":"zone","document":"etiquette","multiple":false},{"enonce":"Quelle est la concentration en Na⁺, en mmol·L⁻¹ ? (Elle vaut aussi celle de Cl⁻.)","aide":"c = m ÷ M : 23,0 mg ÷ 23,0 g·mol⁻¹ donne des mmol.","type":"nombre","unite":"mmol·L⁻¹"},{"enonce":"Calcule la conductivité de l’eau. (1 mmol·L⁻¹ = 1 mol·m⁻³.)","aide":"σ = (λ(Na⁺) + λ(Cl⁻)) × 1,0 mol·m⁻³.","type":"nombre","unite":"mS·m⁻¹"},{"enonce":"Calcule la conductance G de la cellule, en µS. (Convertis σ en S·m⁻¹, S en m² et L en m.)","aide":"σ = 12,6 × 10⁻³ S·m⁻¹ ; S = 2,0 × 10⁻⁴ m² ; L = 1,0 × 10⁻² m.","type":"nombre","unite":"µS"},{"enonce":"En déduire la résistance R = 1/G de la solution, en kΩ. (Deux décimales.)","aide":"R = 1 ÷ G, avec G en siemens.","type":"nombre","unite":"kΩ"},{"enonce":"On éloigne les électrodes : L passe à 2,0 cm. Que devient G, en µS ?","aide":"G est inversement proportionnelle à L.","type":"nombre","unite":"µS"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La ligne **Sodium Na⁺** donne 23,0 mg par litre."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 mmol·L⁻¹","explication":"c = 23,0 ÷ 23,0 = **1,0 mmol·L⁻¹**. Pour Cl⁻ : 35,5 ÷ 35,5 = 1,0 aussi."},{"cle":{"type":"nombre","valeur":12.6,"tolerance":0.05},"affichage":"12,6 mS·m⁻¹","explication":"σ = (5,0 + 7,6) × 1,0 = **12,6 mS·m⁻¹**."},{"cle":{"type":"nombre","valeur":252,"tolerance":1},"affichage":"252 µS","explication":"G = 12,6 × 10⁻³ × 2,0 × 10⁻⁴ ÷ 1,0 × 10⁻² = 2,52 × 10⁻⁴ S = **252 µS**."},{"cle":{"type":"nombre","valeur":3.97,"tolerance":0.02},"affichage":"3,97 kΩ","explication":"R = 1 ÷ 2,52 × 10⁻⁴ ≈ 3 968 Ω ≈ **3,97 kΩ**."},{"cle":{"type":"nombre","valeur":126,"tolerance":1},"affichage":"126 µS","explication":"L double : G est divisée par 2. **126 µS**. La conductivité σ, elle, ne change pas."}]$ex$::jsonb),
