   $ex${"titre":"La bouilloire qui oublie de s’arrêter","competence":"modeliser","situation":"Inès remplit une bouilloire de 0,50 kg d’eau à 20 °C. La bouilloire fournit 2 000 W à l’eau et on néglige toutes les pertes. Elle est défectueuse : elle ne s’arrête pas à 100 °C.","documents":[{"id":"bouilloire","type":"tableau","titre":"Les données","colonnes":["Donnée","Valeur"],"lignes":[["Masse d’eau","0,50 kg"],["Température initiale","20 °C"],["c de l’eau liquide","4185 J·kg⁻¹·K⁻¹"],["L de vaporisation","2,26 × 10⁶ J·kg⁻¹"],["Puissance fournie","2 000 W"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche la donnée qui sert à calculer l’énergie de vaporisation.","aide":"Une vaporisation est un changement d’état.","type":"zone","document":"bouilloire","multiple":false},{"enonce":"Quelle énergie faut-il pour porter l’eau de 20 °C à 100 °C ? Réponds en kJ.","aide":"ΔU = m × c × ΔT, avec ΔT = 80 K.","type":"nombre","unite":"kJ"},{"enonce":"Combien de temps la bouilloire met-elle à porter l’eau à 100 °C ?","aide":"Durée = énergie ÷ puissance.","type":"nombre","unite":"s"},{"enonce":"Quelle énergie faut-il ensuite pour vaporiser toute l’eau à 100 °C ? Réponds en kJ.","aide":"Q = m × L.","type":"nombre","unite":"kJ"},{"enonce":"Combien de temps faudrait-il pour vaporiser toute l’eau ?","aide":"Durée = énergie ÷ puissance.","type":"nombre","unite":"s"}]}$ex$::jsonb,
