   $ex${"titre":"Un réactif qui s’épuise","competence":"lire-graphique","situation":"Au cours d’une transformation, on suit la concentration d’un réactif A au cours du temps.","documents":[{"id":"suivi","type":"graphique","forme":"courbe","titre":"Concentration du réactif A","categories":["0","10","20","30","40","50","60","70","80"],"series":[{"nom":"[A]","valeurs":[80,56.57,40,28.28,20,14.14,10,7.07,5]}],"axeY":{"titre":"[A]","unite":"mmol·L⁻¹","min":0,"max":90,"pas":10},"axeX":{"titre":"Temps (s)"},"valeurs":false,"source":"Mesures idéalisées"}],"questions":[{"enonce":"Quelle est la concentration initiale [A]₀ ?","aide":"Regarde le premier point, à t = 0.","type":"nombre","unite":"mmol·L⁻¹"},{"enonce":"Quel est le temps de demi-réaction ? Cherche la date où [A] est la moitié de [A]₀.","aide":"La moitié de 80 est 40 mmol·L⁻¹.","type":"nombre","unite":"s"},{"enonce":"Touche le point où la vitesse de disparition de A est la plus grande.","aide":"La vitesse est la pente de la tangente : cherche où la courbe est la plus raide.","type":"zone","document":"suivi","multiple":false},{"enonce":"Pourquoi la courbe s’aplatit-elle avec le temps ?","aide":"Pense à la concentration de A.","type":"choix","options":[{"id":"a","texte":"La réaction se fatigue"},{"id":"b","texte":"Il reste moins de réactif"},{"id":"c","texte":"Le catalyseur est consommé"},{"id":"d","texte":"La température baisse forcément"}],"multiple":false}]}$ex$::jsonb,
