 ?","aide":"Il ouvre un autre chemin, plus rapide.","type":"categories","categories":[{"id":"c0","texte":"Il le change"},{"id":"c1","texte":"Il ne le change pas"}],"items":[{"id":"i0","texte":"Le chemin réactionnel"},{"id":"i1","texte":"L’état final"},{"id":"i2","texte":"La durée de la transformation"},{"id":"i3","texte":"La constante d’équilibre"}]}]}$ex$::jsonb,
