  ('5ab70a00-bc96-52ad-862a-dec275c3e28f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois désintégrations","competence":"analyser-document","situation":"Dans toute équation nucléaire, le nombre de nucléons A et la charge Z se conservent. Voici trois désintégrations.","documents":[{"id":"desint","type":"tableau","titre":"Trois équations","colonnes":["Type","Équation"],"lignes":[["α","²²²₈₆Rn → ²¹⁸₈₄Po + ⁴₂He"],["β⁻","¹⁴₆C → ¹⁴₇N + ⁰₋₁e"],["β⁺","²²₁₁Na → ²²₁₀Ne + ⁰₊₁e"]],"enteteLignes":true,"source":"Équations du cours"}],"questions":[{"enonce":"Touche l’équation dans laquelle un neutron se transforme en proton.","aide":"Un neutron qui devient proton fait monter Z de 1 et émet un électron.","type":"zone","document":"desint","multiple":false},{"enonce":"Le radium 226 (Z = 88) émet une particule α. Quel est le numéro atomique Z du noyau fils ?","aide":"La particule α emporte 2 protons.","type":"nombre"},{"enonce":"L’uranium 238 émet une particule α. Quel est le nombre de nucléons A du noyau fils ?","aide":"La particule α emporte 4 nucléons.","type":"nombre"},{"enonce":"Un noyau fils est formé dans un état excité. Comment se désexcite-t-il ?","aide":"Le rayonnement γ n’est pas une désintégration.","type":"choix","options":[{"id":"a","texte":"Il émet une particule α pour retrouver son état de plus basse énergie"},{"id":"b","texte":"Il gagne un neutron, ce qui lui fait évacuer son excès d’énergie"},{"id":"c","texte":"Il émet un photon γ, sans changer son nombre A ni son nombre Z"},{"id":"d","texte":"Il change d’élément chimique pour retrouver son état fondamental"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"En **β⁻**, un neutron devient un proton : Z augmente de 1 (6 → 7)."},{"cle":{"type":"nombre","valeur":86,"tolerance":0},"affichage":"86","explication":"Z = 88 − 2 = **86** : le noyau fils est le radon 222."},{"cle":{"type":"nombre","valeur":234,"tolerance":0},"affichage":"234","explication":"A = 238 − 4 = **234** : le noyau fils est le thorium 234."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il émet un **photon γ** : ni A ni Z ne changent."}]$ex$::jsonb),
  ('5ab70a00-bc96-52ad-862a-dec275c3e28f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La chaîne de l’uranium 238","competence":"raisonner","situation":"L’uranium 238 n’est pas stable : il se désintègre en une longue chaîne jusqu’au plomb 206. Voici le début de cette chaîne.","documents":[{"id":"chaine","type":"chaine","disposition":"ligne","titre":"Début de la chaîne","noeuds":[{"id":"z1","texte":"²³⁸₉₂U"},{"id":"z2","texte":"²³⁴₉₀Th"},{"id":"z3","texte":"?"},{"id":"z4","texte":"²³⁴₉₂U"},{"id":"z5","texte":"²³⁰₉₀Th"}],"liens":[{"de":"z1","a":"z2","texte":"α"},{"de":"z2","a":"z3","texte":"β⁻"},{"de":"z3","a":"z4","texte":"β⁻"},{"de":"z4","a":"z5","texte":"α"}]},{"id":"bilan","type":"tableau","titre":"Début et fin de la chaîne","colonnes":["Noyau","Z","A"],"lignes":[["Uranium 238","92","238"],["Plomb 206","82","206"]],"enteteLignes":true,"source":"Valeurs du cours"}],"questions":[{"enonce":"Quel est le numéro atomique Z du noyau noté « ? » ?","aide":"Une désintégration β⁻ fait monter Z de 1 à partir du thorium 234.","type":"nombre"},{"enonce":"Touche l’isotope de l’uranium 238 dans cette chaîne.","aide":"Un isotope garde le même Z (92) avec un autre A.","type":"zone","document":"chaine","multiple":false},{"enonce":"De l’uranium 238 au plomb 206, combien de désintégrations α se produisent ?","aide":"Seule une α change A : (238 − 206) ÷ 4.","type":"nombre","unite":"α"},{"enonce":"Et combien de désintégrations β⁻ ?","aide":"8 désintégrations α font baisser Z de 16 : compare avec Z du plomb.","type":"nombre","unite":"β⁻"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":91,"tolerance":0},"affichage":"91","explication":"Th (Z = 90) émet un β⁻ : Z = 90 + 1 = **91**. C’est le protactinium 234."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**²³⁴₉₂U** a Z = 92 comme ²³⁸₉₂U, mais A = 234."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 α","explication":"(238 − 206) ÷ 4 = **8** désintégrations α."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 β⁻","explication":"8 α : Z passe de 92 à 92 − 16 = 76. Pour atteindre 82, il faut 82 − 76 = **6** désintégrations β⁻."}]$ex$::jsonb),
  ('544b8892-3512-5ca9-b1d4-552967e43510'::uuid, 1, 1, 5, 20, 4,
