  ('544b8892-3512-5ca9-b1d4-552967e43510'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le charbon de bois de la grotte","competence":"calculer","situation":"Des archéologues datent un charbon de bois trouvé dans une grotte grâce au carbone 14, de demi-vie 5 730 ans. Ils comparent son activité à celle d’un bois vivant.","documents":[{"id":"mesures","type":"tableau","titre":"Mesures au compteur","colonnes":["Échantillon","Activité A (Bq par gramme de carbone)"],"lignes":[["Bois vivant (A₀)",0.23],["Charbon de la grotte (A)",0.092]],"enteteLignes":true,"source":"Valeurs idéalisées"},{"id":"decroit","type":"graphique","forme":"courbe","titre":"Activité d’un bois mort depuis t années","categories":["0","2000","4000","6000","8000","10000","12000","14000","16000","18000","20000"],"series":[{"nom":"A","valeurs":[0.23,0.1806,0.1418,0.1113,0.0874,0.0686,0.0539,0.0423,0.0332,0.0261,0.0205]}],"axeY":{"titre":"Activité","unite":"Bq·g⁻¹","min":0,"max":0.25,"pas":0.05},"axeX":{"titre":"Temps écoulé depuis la mort (années)"},"valeurs":false,"source":"Calculée à partir de A₀ = 0,230 Bq·g⁻¹"}],"questions":[{"enonce":"Calcule la constante radioactive λ du carbone 14 avec λ = ln 2 / t₁/₂, en 10⁻⁴ an⁻¹.","aide":"Divise 0,693 par 5 730.","type":"nombre","unite":"×10⁻⁴ an⁻¹"},{"enonce":"Calcule le rapport A/A₀ pour le charbon.","aide":"Divise la valeur du charbon par celle du bois vivant.","type":"nombre"},{"enonce":"Calcule l’âge du charbon avec t = (1/λ) × ln(A₀/A), à 100 ans près.","aide":"A₀/A = 1/0,40 = 2,5 ; utilise le λ de la première question.","type":"nombre","unite":"ans"},{"enonce":"Sur le graphique, touche le point dont l’activité est la plus proche de celle du charbon.","aide":"Cherche une activité voisine de 0,092 Bq·g⁻¹.","type":"zone","document":"decroit","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1.21,"tolerance":0.01},"affichage":"1,21 ×10⁻⁴ an⁻¹","explication":"λ = 0,693 ÷ 5 730 ≈ **1,21 × 10⁻⁴ an⁻¹**."},{"cle":{"type":"nombre","valeur":0.4,"tolerance":0.005},"affichage":"0,4","explication":"0,092 ÷ 0,230 = **0,40** : il reste 40 % de l’activité d’origine."},{"cle":{"type":"nombre","valeur":7575,"tolerance":100},"affichage":"7575 ans","explication":"t = ln 2,5 ÷ (1,21 × 10⁻⁴) ≈ **7 570 ans** : entre une et deux demi-vies, comme A/A₀ = 0,40 entre 0,5 et 0,25."},{"cle":{"type":"zone","ids":["k4"]},"explication":"À 8 000 ans l’activité vaut environ 0,088 Bq·g⁻¹ : c’est le point le plus proche de 0,092, cohérent avec un âge de **7 570 ans**."}]$ex$::jsonb),
  ('544b8892-3512-5ca9-b1d4-552967e43510'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une dose de technétium à l’hôpital","competence":"modeliser","situation":"Un hôpital prépare à 8 h une dose de technétium 99m (demi-vie 6,0 h) d’activité 600 MBq. Le patient reçoit l’injection à 14 h. Le graphique suit l’activité de la dose depuis 8 h.","documents":[{"id":"dose","type":"graphique","forme":"courbe","titre":"Activité de la dose","categories":["0","3","6","9","12","15","18","21","24"],"series":[{"nom":"A","valeurs":[600,424.3,300,212.1,150,106.1,75,53,37.5]}],"axeY":{"titre":"Activité A","unite":"MBq","min":0,"max":650,"pas":50},"axeX":{"titre":"Temps écoulé depuis 8 h (heures)"},"valeurs":false,"source":"Courbe idéalisée"},{"id":"donnees","type":"tableau","titre":"Données","colonnes":["Grandeur","Valeur"],"lignes":[["Demi-vie t₁/₂","6,0 h"],["Activité à 8 h","600 MBq"],["Heure de l’injection","14 h"],["ln 2","0,693"]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est l’activité de la dose au moment de l’injection, à 14 h ?","aide":"14 h, c’est 6 h après la préparation.","type":"nombre","unite":"MBq"},{"enonce":"Touche le premier point du graphique où l’activité est passée sous 100 MBq.","aide":"Parcours les points : cherche le premier qui est sous la barre des 100 MBq.","type":"zone","document":"dose","multiple":false},{"enonce":"Calcule la constante radioactive λ en h⁻¹ (λ = ln 2 / t₁/₂).","aide":"Divise 0,693 par 6,0 h.","type":"nombre","unite":"h⁻¹"},{"enonce":"Combien de noyaux de technétium 99m contient la dose à l’injection ? Utilise A = λ N avec λ en s⁻¹. Réponds en 10¹² noyaux.","aide":"Convertis 300 MBq en Bq et λ en s⁻¹ (1 h = 3 600 s).","type":"nombre","unite":"×10¹² noyaux"},{"enonce":"Combien d’heures après l’injection l’activité tombera-t-elle à 10 MBq ? Au dixième d’heure.","aide":"De 300 à 10 MBq, l’activité est divisée par 30 : cherche combien de demi-vies donnent 30.","type":"nombre","unite":"h"}]}$ex$::jsonb,
