  ('c253d422-212b-5aa9-8ec9-7b34d79acbee'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le chariot sur le rail","competence":"lire-tableau","situation":"Un chariot descend un rail incliné. Un pointage vidéo relève sa position x toutes les 0,10 s.","documents":[{"id":"pointage","type":"tableau","titre":"Pointage vidéo","colonnes":["Instant t (s)","Position x (cm)"],"lignes":[[0,0],[0.1,0.5],[0.2,2],[0.3,4.5],[0.4,8],[0.5,12.5],[0.6,18]],"enteteLignes":true,"source":"Mesures idéalisées"}],"questions":[{"enonce":"Pour calculer la vitesse à t = 0,20 s, touche les deux positions voisines utilisées dans la différence finie centrée.","aide":"Il faut la position juste avant et la position juste après l’instant 0,20 s.","type":"zone","document":"pointage","multiple":true},{"enonce":"Calcule la vitesse à t = 0,20 s avec v ≈ (x(0,30) − x(0,10)) / (2τ), en cm·s⁻¹.","aide":"τ = 0,10 s, donc 2τ = 0,20 s.","type":"nombre","unite":"cm·s⁻¹"},{"enonce":"Calcule de la même façon la vitesse à t = 0,40 s, en cm·s⁻¹.","aide":"Utilise les positions à 0,30 s et 0,50 s.","type":"nombre","unite":"cm·s⁻¹"},{"enonce":"Déduis l’accélération moyenne entre 0,20 s et 0,40 s, en m·s⁻².","aide":"a = Δv / Δt ; attention aux unités : 100 cm = 1 m.","type":"nombre","unite":"m·s⁻²"}]}$ex$::jsonb,
