  ('c253d422-212b-5aa9-8ec9-7b34d79acbee'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le plateau tournant","competence":"observer-schema","situation":"Un point M du bord d’un plateau de rayon R = 0,50 m fait un tour en T = 2,0 s, à vitesse de valeur constante, dans le sens inverse des aiguilles d’une montre. Le schéma montre le plateau vu de dessus, avec quatre flèches issues de M.","documents":[{"id":"plateau","type":"schema","titre":"Plateau vu de dessus","largeur":340,"hauteur":260,"elements":[{"forme":"cercle","cx":150,"cy":130,"r":90,"teinte":"gris","motif":"aucun"},{"forme":"cercle","cx":150,"cy":130,"r":3,"teinte":"encre","motif":"plein"},{"forme":"texte","x":150,"y":150,"texte":"O","ancre":"milieu"},{"forme":"ligne","de":[240,130],"a":[240,60],"fleche":"fin","id":"z1","zone":true},{"forme":"texte","x":252,"y":58,"texte":"1","gras":true},{"forme":"ligne","de":[240,130],"a":[170,130],"fleche":"fin","id":"z2","zone":true},{"forme":"texte","x":195,"y":120,"texte":"2","gras":true},{"forme":"ligne","de":[240,130],"a":[240,200],"fleche":"fin","id":"z3","zone":true},{"forme":"texte","x":252,"y":208,"texte":"3","gras":true},{"forme":"ligne","de":[240,130],"a":[310,130],"fleche":"fin","id":"z4","zone":true},{"forme":"texte","x":316,"y":122,"texte":"4","gras":true},{"forme":"cercle","cx":240,"cy":130,"r":5,"teinte":"encre","motif":"plein"},{"forme":"texte","x":228,"y":150,"texte":"M","ancre":"milieu"}]}],"questions":[{"enonce":"Touche la flèche qui représente le vecteur vitesse de M.","aide":"Le vecteur vitesse est tangent à la trajectoire, dans le sens du mouvement.","type":"zone","document":"plateau","multiple":false},{"enonce":"Touche la flèche qui représente le vecteur accélération de M.","aide":"Sur une trajectoire courbe, l’accélération est dirigée vers l’intérieur de la courbure.","type":"zone","document":"plateau","multiple":false},{"enonce":"Calcule la valeur de la vitesse v = 2πR / T, en m·s⁻¹.","aide":"Le point parcourt un périmètre 2πR en une période T.","type":"nombre","unite":"m·s⁻¹"},{"enonce":"Calcule la valeur de l’accélération a = v²/R, en m·s⁻².","aide":"Utilise la valeur de v de la question précédente.","type":"nombre","unite":"m·s⁻²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La vitesse est tangente au cercle ; le plateau tourne dans le sens inverse des aiguilles d’une montre : c’est la **flèche 1**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Dans un mouvement circulaire uniforme, l’accélération est centripète : la **flèche 2** pointe vers le centre O."},{"cle":{"type":"nombre","valeur":1.57,"tolerance":0.01},"affichage":"1,57 m·s⁻¹","explication":"v = 2π × 0,50 ÷ 2,0 ≈ **1,57 m·s⁻¹**."},{"cle":{"type":"nombre","valeur":4.93,"tolerance":0.03},"affichage":"4,93 m·s⁻²","explication":"a = 1,57² ÷ 0,50 ≈ **4,93 m·s⁻²**, bien que la valeur de la vitesse soit constante : c’est la direction qui change."}]$ex$::jsonb),
  ('c253d422-212b-5aa9-8ec9-7b34d79acbee'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le virage ralenti","competence":"raisonner","situation":"Une voiture freine régulièrement dans un virage dont la trajectoire est un arc de cercle. Le graphique donne la valeur de sa vitesse, relevée au compteur chaque seconde.","documents":[{"id":"compteur","type":"graphique","forme":"courbe","titre":"Valeur de la vitesse au cours du freinage","categories":["0","1","2","3","4"],"series":[{"nom":"v","valeurs":[15,13,11,9,7]}],"axeY":{"titre":"Vitesse v","unite":"m·s⁻¹","min":0,"max":16,"pas":2},"axeX":{"titre":"Temps (s)"},"valeurs":false,"source":"Relevés idéalisés"},{"id":"virage","type":"fiche","modele":"panneau","entete":"Virage serré","sousTitre":"Trajectoire circulaire","emoji":"🚗","lignes":[{"texte":"Rayon de courbure R","valeur":"50 m"},{"separateur":true},{"texte":"Freinage","valeur":"régulier"}],"pied":"Repère de Frenet : tangente et normale"}],"questions":[{"enonce":"Déduis du graphique la composante tangentielle aₜ = dv/dt, en m·s⁻² (valeur algébrique).","aide":"La vitesse baisse de la même quantité chaque seconde : calcule Δv/Δt.","type":"nombre","unite":"m·s⁻²"},{"enonce":"Calcule la composante normale aₙ = v²/R à t = 0, en m·s⁻².","aide":"Lis v à t = 0 sur le graphique ; R = 50 m.","type":"nombre","unite":"m·s⁻²"},{"enonce":"Calcule la valeur de l’accélération totale à t = 0 : a = √(aₜ² + aₙ²), en m·s⁻².","aide":"Les composantes tangentielle et normale sont perpendiculaires.","type":"nombre","unite":"m·s⁻²"},{"enonce":"Calcule la composante normale à t = 4 s, en m·s⁻².","aide":"Lis d’abord la vitesse à t = 4 s.","type":"nombre","unite":"m·s⁻²"},{"enonce":"Touche l’instant où la composante normale de l’accélération est la plus faible.","aide":"aₙ = v²/R : elle est faible quand v est faible.","type":"zone","document":"compteur","multiple":false}]}$ex$::jsonb,
