  ('10eea279-7e16-5250-b72c-c63cc8272137'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La droite de la diffraction","competence":"experimenter","situation":"Un élève éclaire des fentes de largeurs a variées avec un laser dont il cherche la longueur d’onde. L’écran est à D = 2,00 m. Il mesure la largeur L de la tache centrale et trace L en fonction de 1/a.","documents":[{"id":"fentes","type":"tableau","titre":"Mesures","colonnes":["a (mm)","1/a (mm⁻¹)","L (mm)"],"lignes":[[0.05,20,42.56],[0.1,10,21.28],[0.2,5,10.64]],"enteteLignes":true,"source":"Mesures idéalisées"},{"id":"droite","type":"graphique","forme":"courbe","titre":"L en fonction de 1/a","categories":["0","5","10","15","20","25"],"series":[{"nom":"L","valeurs":[0,10.64,21.28,31.92,42.56,53.2]}],"axeY":{"titre":"L","unite":"mm","min":0,"max":60,"pas":10},"axeX":{"titre":"1/a (mm⁻¹)"},"valeurs":false,"source":"Droite passant par l’origine"}],"questions":[{"enonce":"Calcule 1/a pour une fente de largeur a = 0,040 mm, en mm⁻¹.","aide":"1/0,040 = ?","type":"nombre","unite":"mm⁻¹"},{"enonce":"Touche le point de la droite qui correspond à la fente de a = 0,100 mm.","aide":"Calcule d’abord 1/a pour cette fente.","type":"zone","document":"droite","multiple":false},{"enonce":"Calcule le coefficient directeur de la droite, en mm² (L en mm, 1/a en mm⁻¹).","aide":"Prends le dernier point : 53,2 mm pour 1/a = 25 mm⁻¹ (la droite passe par l’origine).","type":"nombre","unite":"mm²"},{"enonce":"Ce coefficient vaut 2λD. Déduis la longueur d’onde λ du laser, en nm.","aide":"Convertis le coefficient en m², divise par 2D, puis convertis en nm.","type":"nombre","unite":"nm"},{"enonce":"Quel laser l’élève a-t-il utilisé ?","aide":"Compare ta valeur de λ aux longueurs d’onde proposées.","type":"choix","options":[{"id":"a","texte":"Un laser infrarouge de 980 nm"},{"id":"b","texte":"Un laser vert de 532 nm"},{"id":"c","texte":"Un laser bleu de 450 nm"},{"id":"d","texte":"Un laser rouge de 650 nm"}],"multiple":false}]}$ex$::jsonb,
