  ('634303eb-61ee-5bff-92ba-5f31627b1602'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Brillant ou sombre ?","competence":"calculer","situation":"Un laser de longueur d’onde λ = 500 nm éclaire deux fentes d’Young. En six points de l’écran, on a calculé la différence de marche δ. Les interférences sont constructives si δ = kλ et destructives si δ = (k + ½)λ, avec k entier.","documents":[{"id":"marche","type":"tableau","titre":"Différence de marche aux six points","colonnes":["Point","δ (nm)"],"lignes":[["M1",250],["M2",500],["M3",750],["M4",1000],["M5",1250],["M6",1750]],"enteteLignes":true,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Touche les valeurs de δ pour lesquelles on observe une frange brillante.","aide":"Cherche les δ qui sont un nombre entier de fois 500 nm.","type":"zone","document":"marche","multiple":true},{"enonce":"Calcule δ/λ pour le point M6.","aide":"Divise 1 750 nm par 500 nm.","type":"nombre"},{"enonce":"On remplace le laser par un laser de 650 nm. Le point où δ = 1 300 nm est…","aide":"Calcule 1 300 ÷ 650.","type":"choix","options":[{"id":"a","texte":"Sur une frange brillante, car δ = 2 λ"},{"id":"b","texte":"Sur une frange sombre, car δ = 2,5 λ"},{"id":"c","texte":"Sur une frange sombre, car δ = 2 λ"},{"id":"d","texte":"Sur une frange brillante, car δ = 1,5 λ"}],"multiple":false},{"enonce":"Avec ce laser de 650 nm, quelle est la plus petite différence de marche non nulle donnant une frange sombre ? Réponds en nm.","aide":"La condition est δ = (k + ½) λ avec k = 0.","type":"nombre","unite":"nm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1","r3c1"]},"explication":"500 nm = 1 λ et 1 000 nm = 2 λ : les points **M2 et M4** sont sur des franges brillantes. Les autres valeurs sont des multiples impairs de λ/2 : franges sombres."},{"cle":{"type":"nombre","valeur":3.5,"tolerance":0.02},"affichage":"3,5","explication":"1 750 ÷ 500 = **3,5** = 3 + ½ : interférences destructives, frange sombre."},{"cle":{"type":"choix","ids":["a"]},"explication":"1 300 ÷ 650 = 2 : δ est un nombre entier de λ, donc la frange est **brillante**."},{"cle":{"type":"nombre","valeur":325,"tolerance":1},"affichage":"325 nm","explication":"δ = ½ λ = 650 ÷ 2 = **325 nm**."}]$ex$::jsonb),
  ('634303eb-61ee-5bff-92ba-5f31627b1602'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le silence entre deux haut-parleurs","competence":"experimenter","situation":"Deux haut-parleurs branchés sur le même générateur émettent en phase un son pur de fréquence f = 1 700 Hz. Un micro est placé en six points M1 à M6 ; on relève ses distances d₁ et d₂ aux deux haut-parleurs. La célérité du son est c = 340 m·s⁻¹.","documents":[{"id":"distances","type":"tableau","titre":"Distances aux deux haut-parleurs","colonnes":["Point","d₁ (m)","d₂ (m)"],"lignes":[["M1",2.5,2.5],["M2",2.5,2.6],["M3",3,3.2],["M4",2.8,3.1],["M5",3.1,3.5],["M6",3.2,3.7]],"enteteLignes":true,"source":"Mesures idéalisées"},{"id":"niveaux","type":"graphique","forme":"barres","titre":"Niveau sonore mesuré en chaque point","categories":["M1","M2","M3","M4","M5","M6"],"series":[{"nom":"L","valeurs":[72,36,72,38,71,40],"teinte":"turquoise"}],"axeY":{"titre":"Niveau L","unite":"dB","min":0,"max":80,"pas":10},"axeX":{"titre":"Point de mesure"},"valeurs":false,"source":"Mesures idéalisées"}],"questions":[{"enonce":"Calcule la longueur d’onde λ = c / f du son, en m.","aide":"Divise la célérité par la fréquence.","type":"nombre","unite":"m"},{"enonce":"Calcule la différence de marche δ = |d₂ − d₁| au point M4, en m.","aide":"Soustrais les deux distances de la ligne M4.","type":"nombre","unite":"m"},{"enonce":"Calcule δ/λ au point M6.","aide":"δ = 3,70 − 3,20, puis divise par λ.","type":"nombre"},{"enonce":"Touche les points où les interférences sont destructives, c’est-à-dire où δ = (k + ½) λ.","aide":"Calcule δ pour chaque point, puis δ/λ : cherche les demi-entiers (0,5 ; 1,5 ; 2,5).","type":"zone","document":"distances","multiple":true},{"enonce":"Sur le graphique, le niveau en M2 n’est pas nul (36 dB). Que faut-il en conclure ?","aide":"Le son des deux haut-parleurs est cohérent. Que peut-on dire de leurs amplitudes au niveau du micro ?","type":"choix","options":[{"id":"a","texte":"L’énergie sonore est détruite et le reste du son vient d’ailleurs, d’une autre source"},{"id":"b","texte":"Le calcul de la différence de marche δ est faux, car il n’y a pas de silence en M2"},{"id":"c","texte":"Les ondes ne s’annulent pas tout à fait : amplitudes un peu inégales, réflexions du son"},{"id":"d","texte":"Les deux haut-parleurs ne sont pas cohérents, donc ils n’interfèrent pas du tout"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.2,"tolerance":0.005},"affichage":"0,2 m","explication":"λ = 340 ÷ 1 700 = **0,200 m**."},{"cle":{"type":"nombre","valeur":0.3,"tolerance":0.005},"affichage":"0,3 m","explication":"δ = 3,10 − 2,80 = **0,30 m**."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0.02},"affichage":"2,5","explication":"δ = 0,50 m ; δ/λ = 0,50 ÷ 0,20 = **2,5** : c’est un demi-entier."},{"cle":{"type":"zone","ids":["r1c0","r3c0","r5c0"]},"explication":"δ/λ = 0,5 en M2, 1,5 en M4 et 2,5 en M6 : ce sont les trois points de **silence** prévu. Les autres donnent 0, 1 et 2 : interférences constructives."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le niveau chute de plus de 30 dB entre M1 et M2 : l’interférence destructive est bien là. Elle n’est pas parfaite car les amplitudes en M2 sont légèrement inégales et la salle réfléchit un peu de son."}]$ex$::jsonb),
  ('b871cc0d-ec23-5929-b049-a037dd850591'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les oculaires de la lunette","competence":"lire-tableau","situation":"Une lunette astronomique afocale a un objectif de distance focale f′₁ = 1 000 mm. Un astronome dispose de trois oculaires de focales différentes.","documents":[{"id":"oculaires","type":"tableau","titre":"Les trois oculaires","colonnes":["Oculaire","Distance focale f′₂ (mm)"],"lignes":[["Oculaire A",25],["Oculaire B",10],["Oculaire C",5]],"enteteLignes":true,"source":"Valeurs du catalogue imaginé pour l’exercice"}],"questions":[{"enonce":"Calcule le grossissement G = f′₁ / f′₂ avec l’oculaire A.","aide":"Divise la focale de l’objectif par celle de l’oculaire.","type":"nombre"},{"enonce":"Touche l’oculaire qui donne le plus fort grossissement.","aide":"G = f′₁ / f′₂ : quel f′₂ rend G le plus grand ?","type":"zone","document":"oculaires","multiple":false},{"enonce":"Avec l’oculaire A, quelle est la distance entre l’objectif et l’oculaire (montage afocal : F′₁ = F₂), en mm ?","aide":"Les deux lentilles sont séparées de f′₁ + f′₂.","type":"nombre","unite":"mm"},{"enonce":"La Lune est vue sous le diamètre apparent θ = 9,3 × 10⁻³ rad. Quel est le diamètre de son image A₁B₁ dans le plan focal de l’objectif (A₁B₁ = f′₁ × θ), en mm ?","aide":"Exprime f′₁ en mm et garde θ en radians.","type":"nombre","unite":"mm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":40,"tolerance":0.5},"affichage":"40","explication":"G = 1 000 ÷ 25 = **40**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"G est le plus grand pour la focale d’oculaire la plus courte : l’**oculaire C** (5 mm) donne G = 200."},{"cle":{"type":"nombre","valeur":1025,"tolerance":1},"affichage":"1025 mm","explication":"Le foyer image de l’objectif coïncide avec le foyer objet de l’oculaire : distance = 1 000 + 25 = **1 025 mm**."},{"cle":{"type":"nombre","valeur":9.3,"tolerance":0.1},"affichage":"9,3 mm","explication":"A₁B₁ = 1 000 × 9,3 × 10⁻³ = **9,3 mm**."}]$ex$::jsonb),
  ('b871cc0d-ec23-5929-b049-a037dd850591'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le banc d’optique","competence":"experimenter","situation":"Sur un banc d’optique, on place un objet AB de 2,0 cm de hauteur devant une lentille mince convergente et on relève la position OA′ de l’image nette pour quatre positions OA de l’objet. Les mesures sont algébriques, en cm.","documents":[{"id":"banc","type":"tableau","titre":"Positions de l’objet et de l’image","colonnes":["OA (cm)","OA′ (cm)"],"lignes":[["−25",100],["−30",60],["−40",40],["−60",30]],"enteteLignes":true,"source":"Mesures idéalisées"}],"questions":[{"enonce":"Touche la valeur de OA′ pour laquelle l’image a la même taille que l’objet (|OA′| = |OA|).","aide":"Cherche la ligne où les deux nombres ont la même valeur absolue.","type":"zone","document":"banc","multiple":false},{"enonce":"Avec cette ligne, calcule la distance focale f′ avec 1/f′ = 1/OA′ − 1/OA, en cm.","aide":"OA = −40 cm et OA′ = 40 cm : 1/40 − (−1/40).","type":"nombre","unite":"cm"},{"enonce":"Calcule la vergence V = 1/f′ de la lentille, en dioptries (f′ en mètres).","aide":"20 cm = 0,20 m.","type":"nombre","unite":"δ"},{"enonce":"Calcule le grandissement γ = OA′/OA pour la ligne OA = −25 cm.","aide":"OA′ = 100 cm pour cette ligne.","type":"nombre"},{"enonce":"Quelle est la hauteur algébrique A′B′ de l’image de AB = 2,0 cm pour cette ligne, en cm ?","aide":"A′B′ = γ × AB.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Pour OA = −40 cm, on a OA′ = 40 cm : |γ| = 1."},{"cle":{"type":"nombre","valeur":20,"tolerance":0.2},"affichage":"20 cm","explication":"1/f′ = 1/40 + 1/40 = 1/20 : f′ = **20 cm**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0.05},"affichage":"5 δ","explication":"V = 1 ÷ 0,20 = **5,0 δ**."},{"cle":{"type":"nombre","valeur":-4,"tolerance":0.05},"affichage":"−4","explication":"γ = 100 ÷ (−25) = **−4,0** : l’image est renversée et quatre fois plus grande."},{"cle":{"type":"nombre","valeur":-8,"tolerance":0.1},"affichage":"−8 cm","explication":"A′B′ = −4,0 × 2,0 = **−8,0 cm**."}]$ex$::jsonb),
  ('b871cc0d-ec23-5929-b049-a037dd850591'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Jupiter dans la lunette","competence":"raisonner","situation":"Un amateur observe Jupiter avec une lunette afocale : objectif de focale f′₁ = 1 200 mm et de diamètre D = 100 mm. Jupiter est vue sous le diamètre apparent θ = 2,2 × 10⁻⁴ rad. On prend λ = 550 nm et la limite de diffraction θ_lim = λ / D.","documents":[{"id":"grossissement","type":"graphique","forme":"courbe","titre":"Grossissement selon l’oculaire","categories":["40","30","25","20","15","10","5"],"series":[{"nom":"G","valeurs":[30,40,48,60,80,120,240]}],"axeY":{"titre":"Grossissement G","unite":"","min":0,"max":250,"pas":50},"axeX":{"titre":"Focale de l’oculaire f′₂ (mm)"},"valeurs":false,"source":"G = f′₁ / f′₂"},{"id":"doubles","type":"tableau","titre":"Deux étoiles doubles","colonnes":["Système","Écart angulaire entre les deux étoiles"],"lignes":[["Double A","2,0 µrad"],["Double B","9,0 µrad"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’oculaire qui donne un grossissement de 60.","aide":"G = 1 200 ÷ f′₂ : cherche la focale qui donne 60.","type":"zone","document":"grossissement","multiple":false},{"enonce":"Avec l’oculaire de 15 mm, calcule le diamètre apparent θ′ de Jupiter vue dans la lunette (θ′ = G θ), en 10⁻² rad.","aide":"G = 1 200 ÷ 15 = 80.","type":"nombre","unite":"×10⁻² rad"},{"enonce":"Quel est le diamètre de l’image intermédiaire A₁B₁ de Jupiter dans le plan focal de l’objectif (A₁B₁ = f′₁ × θ), en mm ?","aide":"Garde f′₁ en mm et θ en radians.","type":"nombre","unite":"mm"},{"enonce":"Calcule la limite de diffraction θ_lim = λ / D de l’objectif, en µrad (1 µrad = 10⁻⁶ rad).","aide":"Mets D = 100 mm en mètres.","type":"nombre","unite":"µrad"},{"enonce":"Touche le système d’étoiles doubles que cette lunette peut séparer, quel que soit l’oculaire.","aide":"Il faut que l’écart angulaire soit supérieur à la limite de diffraction.","type":"zone","document":"doubles","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"G = 1 200 ÷ 20 = 60 : c’est l’oculaire de **20 mm**."},{"cle":{"type":"nombre","valeur":1.76,"tolerance":0.01},"affichage":"1,76 ×10⁻² rad","explication":"θ′ = 80 × 2,2 × 10⁻⁴ = **1,76 × 10⁻² rad**, soit environ 1°."},{"cle":{"type":"nombre","valeur":0.264,"tolerance":0.005},"affichage":"0,264 mm","explication":"A₁B₁ = 1 200 × 2,2 × 10⁻⁴ = **0,264 mm**."},{"cle":{"type":"nombre","valeur":5.5,"tolerance":0.05},"affichage":"5,5 µrad","explication":"θ_lim = 550 × 10⁻⁹ ÷ 0,100 = 5,5 × 10⁻⁶ rad = **5,5 µrad**."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Seul l’écart de 9,0 µrad (**Double B**) dépasse 5,5 µrad. Pour la double A, changer d’oculaire ne fait qu’agrandir une image floue : c’est le « grossissement vide »."}]$ex$::jsonb),
  ('b5920b02-7a95-5d73-bcee-57be389a7914'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois diodes, trois énergies","competence":"lire-graphique","situation":"Une lampe de poche contient trois diodes électroluminescentes. On donne h = 6,63 × 10⁻³⁴ J·s, c = 3,00 × 10⁸ m·s⁻¹ et 1 eV = 1,60 × 10⁻¹⁹ J.","documents":[{"id":"diodes","type":"graphique","forme":"barres","titre":"Longueur d’onde de chaque diode","categories":["Diode rouge","Diode verte","Diode bleue"],"series":[{"nom":"λ","valeurs":[650,530,450]}],"axeY":{"titre":"Longueur d’onde","unite":"nm","min":0,"max":700,"pas":100},"axeX":{"titre":"Diode"},"valeurs":true,"source":"Valeurs arrondies, écrites pour l’exercice"}],"questions":[{"enonce":"Touche la diode dont les photons transportent le plus d’énergie.","aide":"E = h c / λ : quand λ diminue, l’énergie du photon augmente.","type":"zone","document":"diodes","multiple":false},{"enonce":"Calcule l’énergie d’un photon de la diode bleue, en 10⁻¹⁹ J (arrondie au centième). Convertis λ en mètres.","aide":"λ = 450 nm = 450 × 10⁻⁹ m. Utilise E = h c / λ.","type":"nombre","unite":"× 10⁻¹⁹ J"},{"enonce":"Exprime cette énergie en électronvolts (arrondie au centième).","aide":"Divise par 1,60 × 10⁻¹⁹ J, qui vaut 1 eV.","type":"nombre","unite":"eV"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"**La diode bleue** a la plus petite longueur d’onde (450 nm) : ses photons sont les plus énergétiques."},{"cle":{"type":"nombre","valeur":4.42,"tolerance":0.02},"affichage":"4,42 × 10⁻¹⁹ J","explication":"E = 6,63 × 10⁻³⁴ × 3,00 × 10⁸ ÷ (450 × 10⁻⁹) ≈ **4,42 × 10⁻¹⁹ J**."},{"cle":{"type":"nombre","valeur":2.76,"tolerance":0.03},"affichage":"2,76 eV","explication":"4,42 × 10⁻¹⁹ ÷ 1,60 × 10⁻¹⁹ ≈ **2,76 eV**."}]$ex$::jsonb),
  ('b5920b02-7a95-5d73-bcee-57be389a7914'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La cellule photoélectrique","competence":"analyser-document","situation":"Une cellule photoélectrique est éclairée par une lumière violette de longueur d’onde 400 nm. On donne h = 6,63 × 10⁻³⁴ J·s, c = 3,00 × 10⁸ m·s⁻¹ et 1 eV = 1,60 × 10⁻¹⁹ J.","documents":[{"id":"metaux","type":"graphique","forme":"barres","titre":"Travail d’extraction de quatre métaux","categories":["Césium","Potassium","Zinc","Platine"],"series":[{"nom":"W₀","valeurs":[2.1,2.3,4.3,5.6]}],"axeY":{"titre":"Travail d’extraction W₀","unite":"eV","min":0,"max":6,"pas":1},"axeX":{"titre":"Métal"},"valeurs":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Calcule l’énergie d’un photon de 400 nm, en eV (arrondie au dixième).","aide":"E = h c / λ en joules, puis divise par 1,60 × 10⁻¹⁹.","type":"nombre","unite":"eV"},{"enonce":"Touche tous les métaux qui peuvent émettre des électrons sous cette lumière.","aide":"Il faut que l’énergie d’un photon dépasse W₀.","type":"zone","document":"metaux","multiple":true},{"enonce":"Quelle énergie cinétique maximale, en eV, un électron arraché au césium emporte-t-il ? Arrondis au dixième.","aide":"Ec max = énergie du photon − W₀.","type":"nombre","unite":"eV"},{"enonce":"On remplace la lampe par une lampe violette dix fois plus intense. Peut-on maintenant arracher des électrons au zinc ?","aide":"Un électron reçoit un seul photon, jamais plusieurs à la fois.","type":"choix","options":[{"id":"a","texte":"Oui : dix fois plus de photons apportent dix fois plus d’énergie à un électron"},{"id":"b","texte":"Non, car l’énergie des photons baisse quand la lampe est plus intense"},{"id":"c","texte":"Oui, mais seulement après quelques minutes d’éclairement"},{"id":"d","texte":"Non : chaque photon garde 3,1 eV, inférieur à W₀"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3.1,"tolerance":0.05},"affichage":"3,1 eV","explication":"E = 6,63 × 10⁻³⁴ × 3,00 × 10⁸ ÷ (400 × 10⁻⁹) ≈ 4,97 × 10⁻¹⁹ J, soit **3,1 eV**."},{"cle":{"type":"zone","ids":["k0","k1"]},"explication":"Seuls le **césium** (2,1 eV) et le **potassium** (2,3 eV) ont un W₀ inférieur à 3,1 eV."},{"cle":{"type":"nombre","valeur":1,"tolerance":0.05},"affichage":"1 eV","explication":"Ec = 3,11 − 2,1 ≈ **1,0 eV**."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’intensité change le **nombre** de photons, pas leur énergie. Avec 3,1 eV < 4,3 eV, aucun électron n’est arraché au zinc."}]$ex$::jsonb),
  ('b5920b02-7a95-5d73-bcee-57be389a7914'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les raies de l’hydrogène","competence":"modeliser","situation":"Voici les premiers niveaux d’énergie de l’atome d’hydrogène (échelle non respectée). On donne h = 6,63 × 10⁻³⁴ J·s, c = 3,00 × 10⁸ m·s⁻¹ et 1 eV = 1,60 × 10⁻¹⁹ J.","documents":[{"id":"niveaux","type":"schema","titre":"Niveaux d’énergie de l’hydrogène","largeur":340,"hauteur":250,"elements":[{"forme":"ligne","de":[70,215],"a":[250,215]},{"forme":"texte","x":20,"y":219,"texte":"n = 1","ancre":"debut"},{"forme":"texte","x":258,"y":219,"texte":"−13,6 eV","ancre":"debut"},{"forme":"ligne","de":[70,135],"a":[250,135]},{"forme":"texte","x":20,"y":139,"texte":"n = 2","ancre":"debut"},{"forme":"texte","x":258,"y":139,"texte":"−3,40 eV","ancre":"debut"},{"forme":"ligne","de":[70,95],"a":[250,95]},{"forme":"texte","x":20,"y":99,"texte":"n = 3","ancre":"debut"},{"forme":"texte","x":258,"y":99,"texte":"−1,51 eV","ancre":"debut"},{"forme":"ligne","de":[70,60],"a":[250,60]},{"forme":"texte","x":20,"y":64,"texte":"n = 4","ancre":"debut"},{"forme":"texte","x":258,"y":64,"texte":"−0,85 eV","ancre":"debut"},{"forme":"ligne","de":[110,95],"a":[110,135],"fleche":"fin"},{"forme":"rect","x":86,"y":104,"l":48,"h":22,"texte":"3 → 2","teinte":"blanc","motif":"plein","id":"z1","zone":true},{"forme":"ligne","de":[160,60],"a":[160,135],"fleche":"fin"},{"forme":"rect","x":136,"y":86.5,"l":48,"h":22,"texte":"4 → 2","teinte":"blanc","motif":"plein","id":"z2","zone":true},{"forme":"ligne","de":[210,60],"a":[210,95],"fleche":"fin"},{"forme":"rect","x":186,"y":66.5,"l":48,"h":22,"texte":"4 → 3","teinte":"blanc","motif":"plein","id":"z3","zone":true}]},{"id":"raies","type":"tableau","titre":"Raies visibles observées","colonnes":["Raie","Longueur d’onde (nm)"],"lignes":[["1",656],["2",486],["3",434]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Quelle énergie, en eV, l’atome émet-il en passant du niveau n = 3 au niveau n = 2 ?","aide":"ΔE = E₃ − E₂, avec les valeurs du schéma.","type":"nombre","unite":"eV"},{"enonce":"Quelle est la longueur d’onde du photon émis pour cette transition, en nm (arrondie à l’unité) ?","aide":"Convertis ΔE en joules, puis λ = h c / ΔE.","type":"nombre","unite":"nm"},{"enonce":"Touche la transition qui produit la raie de 486 nm du tableau.","aide":"Calcule ΔE puis λ pour chaque transition. L’une sort du visible.","type":"zone","document":"niveaux","multiple":false},{"enonce":"Un photon de 2,00 eV traverse des atomes d’hydrogène dans le niveau n = 2. Que se passe-t-il ?","aide":"À partir de n = 2, les écarts possibles sont 1,89 eV (vers n = 3) et 2,55 eV (vers n = 4).","type":"choix","options":[{"id":"a","texte":"Il est absorbé et l’atome passe au niveau n = 3, en gardant le surplus"},{"id":"b","texte":"Il est toujours absorbé si la lumière est assez intense"},{"id":"c","texte":"Il n’est pas absorbé : aucun écart entre deux niveaux ne vaut 2,00 eV"},{"id":"d","texte":"Il est absorbé en partie, selon son intensité"}],"multiple":false}]}$ex$::jsonb,
