  ('6c04d56f-52f5-5a5b-98e5-a05b5f0a765d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Choisir sa voie de synthèse","competence":"resoudre","situation":"Pour préparer une molécule P, trois voies sont envisagées. Dans l’étape voulue, le réactif 1 (M = 120 g·mol⁻¹) et le réactif 2 (M = 60 g·mol⁻¹) donnent P (M = 150 g·mol⁻¹) et un unique sous-produit (M = 30 g·mol⁻¹).","documents":[{"id":"voies","type":"tableau","titre":"Les trois voies","colonnes":["Voie","Étapes (rendements)","Réactifs"],"lignes":[["A, avec protection","95 % · 80 % · 90 %","bon marché"],["B, sans protection","1 étape : 45 % de P","bon marché"],["C, réactif sélectif","1 étape : 70 %","très cher, toxique"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Calcule le rendement global de la voie A (protection, étape voulue, déprotection), en % (arrondi à l’unité).","aide":"Multiplie les trois rendements en nombres décimaux.","type":"nombre","unite":"%"},{"enonce":"Touche, dans la première colonne, la voie qui a le meilleur rendement global.","aide":"Compare 68 %, 45 % et 70 %.","type":"zone","document":"voies","multiple":false},{"enonce":"Malgré ce rendement, pourquoi peut-on écarter la voie C ?","aide":"Regarde la colonne « Réactifs » du tableau.","type":"choix","options":[{"id":"a","texte":"Une voie à une seule étape est toujours moins sélective qu’une voie à plusieurs"},{"id":"b","texte":"Elle impose forcément une protection de fonction, ce qui alourdit beaucoup la synthèse"},{"id":"c","texte":"Un rendement de 70 % est impossible à atteindre en pratique dans une synthèse réelle"},{"id":"d","texte":"Son réactif est cher et toxique : coût et sécurité comptent autant que le rendement"}],"multiple":false},{"enonce":"Calcule l’économie d’atomes de l’étape voulue, M(P) ÷ somme des M des réactifs, en % (arrondie à l’unité).","aide":"Somme des réactifs : 120 + 60 = 180 g·mol⁻¹.","type":"nombre","unite":"%"},{"enonce":"Avec 12,0 g de réactif 1 et la voie A, calcule la masse de P obtenue, en g (arrondie au dixième).","aide":"n(réactif 1) =